#include "materials.hpp"
#include <algorithm>
#include <cmath>
#include <fstream>
#include <stdexcept>
namespace kartgib::materials {
static float clamp(float v){return std::clamp(v,0.f,1.f);} 
uint32_t hash2(int x,int y,uint32_t seed){uint32_t h=seed ^ (uint32_t(x)*0x9e3779b9u) ^ (uint32_t(y)*0x85ebca6bu);h^=h>>16;h*=0x7feb352du;h^=h>>15;h*=0x846ca68bu;return h^(h>>16);}
static float rnd(int x,int y,uint32_t s){return float(hash2(x,y,s)>>8)*(1.f/16777216.f);}
float smoothstep(float a,float b,float x){if(a==b)return x>=b?1.f:0.f;float t=clamp((x-a)/(b-a));return t*t*(3.f-2.f*t);}
float noise2(float x,float y,uint32_t seed){int ix=int(std::floor(x)),iy=int(std::floor(y));float u=smoothstep(0,1,x-ix),v=smoothstep(0,1,y-iy);float a=std::lerp(rnd(ix,iy,seed),rnd(ix+1,iy,seed),u);float b=std::lerp(rnd(ix,iy+1,seed),rnd(ix+1,iy+1,seed),u);return std::lerp(a,b,v);}
float fbm(float x,float y,uint32_t seed,int octaves){float v=0,amp=.5f,sum=0;for(int i=0;i<std::clamp(octaves,1,10);++i){v+=amp*noise2(x,y,seed+uint32_t(i)*1237u);sum+=amp;amp*=.5f;x*=2.03f;y*=2.03f;}return v/sum;}
float voronoi(float x,float y,uint32_t seed){int ix=int(std::floor(x)),iy=int(std::floor(y));float best=100;for(int j=-1;j<=1;++j)for(int i=-1;i<=1;++i){float dx=float(ix+i)+rnd(ix+i,iy+j,seed)-x,dy=float(iy+j)+rnd(ix+i,iy+j,seed+17)-y;best=std::min(best,dx*dx+dy*dy);}return clamp(std::sqrt(best));}
PBR preset(Surface s){switch(s){case Surface::Asphalt:return {{.095f,.10f,.11f},.94f,0,.96f,0};case Surface::RoadLine:return {{.94f,.89f,.69f},.65f,0,1,0};case Surface::Kerb:return {{.82f,.12f,.09f},.77f,0,1,0};case Surface::Stone:return {{.40f,.38f,.34f},.91f,0,1,0};case Surface::Rock:return {{.33f,.32f,.29f},.97f,0,1,0};case Surface::Sand:return {{.78f,.64f,.39f},1,0,1,0};case Surface::Grass:return {{.19f,.36f,.10f},.95f,0,1,0};case Surface::Snow:return {{.88f,.92f,.96f},.82f,0,1,0};case Surface::PaintedMetal:return {{.14f,.32f,.77f},.28f,.67f,1,0};case Surface::BareMetal:return {{.59f,.62f,.66f},.22f,1,1,0};case Surface::Neon:return {{.03f,.56f,1.f},.3f,.1f,1,4.f};case Surface::Dirt:return {{.30f,.19f,.11f},1,0,1,0};case Surface::Foliage:return {{.09f,.30f,.07f},.92f,0,1,0};case Surface::Water:return {{.04f,.28f,.43f},.08f,0,1,0};case Surface::Glass:return {{.64f,.79f,.9f},.07f,0,1,0};}return {};}
float asphalt_grain(float x,float y,uint32_t seed){return clamp(.65f*fbm(x*25,y*25,seed,4)+.35f*rnd(int(x*512),int(y*512),seed));}
float road_marking(float u,float v){float line=1.f-smoothstep(.015f,.03f,std::abs(u-.5f));float dash=std::fmod(v*8.f,1.f)<.62f?1.f:0.f;return clamp(line*dash);}
float kerb_stripes(float u,float v){(void)v;return (int(std::floor(u*12.f))&1)?1.f:0.f;}
float stone_mortar(float u,float v){float row=std::floor(v*8.f),offset=std::fmod(row,2.f)*.5f;float fx=u*8.f+offset-std::floor(u*8.f+offset),fy=v*8.f-std::floor(v*8.f);return 1.f-std::max(smoothstep(.025f,.055f,std::min(fx,1.f-fx)),smoothstep(.025f,.055f,std::min(fy,1.f-fy)));}
float terrain_blend(float height,float slope){return clamp(smoothstep(.25f,.75f,height)*(.7f+.3f*clamp(slope)));}
float metal_wear(float u,float v,uint32_t seed){float edge=1.f-smoothstep(0,.08f,std::min({u,v,1.f-u,1.f-v}));return clamp(edge*.7f+std::pow(noise2(u*45,v*45,seed),5.f)*.5f);}
Vec3 normal_from_height(const std::vector<float>& h,int w,int ht,int x,int y,float strength){if(w<=0||ht<=0||h.size()!=size_t(w)*size_t(ht))return {0,0,1};auto at=[&](int a,int b){return h[size_t(std::clamp(b,0,ht-1))*w+std::clamp(a,0,w-1)];};float dx=(at(x+1,y)-at(x-1,y))*strength,dy=(at(x,y+1)-at(x,y-1))*strength;float l=std::sqrt(dx*dx+dy*dy+1.f);return {-dx/l,-dy/l,1.f/l};}
TextureSet bake(const Config& c){if(c.width<1||c.height<1||c.width>4096||c.height>4096||!std::isfinite(c.scale)||c.scale<=0)throw std::invalid_argument("invalid material bake configuration");TextureSet t;t.width=c.width;t.height=c.height;size_t n=size_t(c.width)*c.height;t.albedo.resize(n);t.normal.resize(n);t.orm.resize(n);t.emissive.resize(n);std::vector<float> heights(n);PBR p=preset(c.surface);for(int y=0;y<c.height;++y)for(int x=0;x<c.width;++x){size_t i=size_t(y)*c.width+x;float u=(x+.5f)/c.width,v=(y+.5f)/c.height;float n0=fbm(u*c.scale,v*c.scale,c.seed),detail=n0,mark=0;switch(c.surface){case Surface::Asphalt:detail=asphalt_grain(u*c.scale,v*c.scale,c.seed);break;case Surface::RoadLine:mark=road_marking(u,v);break;case Surface::Kerb:mark=kerb_stripes(u,v);break;case Surface::Stone:mark=stone_mortar(u,v);break;case Surface::Rock:detail=voronoi(u*c.scale,v*c.scale,c.seed);break;case Surface::Sand:detail=noise2(u*c.scale*16,v*c.scale*16,c.seed);break;case Surface::PaintedMetal:case Surface::BareMetal:detail=metal_wear(u,v,c.seed);break;default:break;}heights[i]=detail;float shade=.75f+.45f*detail;if(c.surface==Surface::Stone)shade*=1.f-.6f*mark;if(c.surface==Surface::RoadLine)shade=.15f+.85f*mark;if(c.surface==Surface::Kerb)shade=mark?.92f:.32f;t.albedo[i]={clamp(p.albedo.x*shade),clamp(p.albedo.y*shade),clamp(p.albedo.z*shade),1};t.orm[i]={clamp(p.ao),clamp(p.roughness+(.5f-detail)*.15f),clamp(p.metallic),1};t.emissive[i]={p.albedo.x*p.emissive,p.albedo.y*p.emissive,p.albedo.z*p.emissive,1};}for(int y=0;y<c.height;++y)for(int x=0;x<c.width;++x){auto nrm=normal_from_height(heights,c.width,c.height,x,y,2.f);t.normal[size_t(y)*c.width+x]={nrm.x*.5f+.5f,nrm.y*.5f+.5f,nrm.z*.5f+.5f,1};}return t;}
bool write_ppm(const char* path,const TextureSet& t){if(!path||t.width<1||t.height<1||t.albedo.size()!=size_t(t.width)*t.height)return false;std::ofstream out(path,std::ios::binary);if(!out)return false;out<<"P6\n"<<t.width<<" "<<t.height<<"\n255\n";for(const auto& p:t.albedo){char rgb[3]={char(int(clamp(p.r)*255+.5f)),char(int(clamp(p.g)*255+.5f)),char(int(clamp(p.b)*255+.5f))};out.write(rgb,3);}return bool(out);}
}
